/* Only the 21 owner-selected light originals: legacy magenta cards stay white. */
.visual-card--original .visual-card__inner { background: var(--original-image-bg, #fefefe); }
.visual-card--original .visual-card__image { object-fit: contain; object-position: 50% 100%; }
/* This original's document starts higher: retain the full image below the copy. */
.visual-card--original[data-original-asset="HOME-02"] .visual-card__image { top: auto; height: 85%; }
.visual-card--original[data-original-asset="PLANNER-04"] .visual-card__image { top: auto; height: 80%; }
/* The taller AI source needs copy clearance; keep the whole 2:3 composition. */
.visual-card--original[data-original-asset="AI-02"] .visual-card__image { top: auto; height: 85%; }
/* Keep the high authorization panel below the existing multi-line AI copy. */
.visual-card--original[data-original-asset="AI-08"] .visual-card__image { top: auto; height: 80%; }
@media (max-width: 720px) {
  .visual-card--original[data-original-asset="HOME-03"] .visual-card__image { top: auto; height: 90%; }
}
.visual-card--original .visual-card__copy,
.visual-card--original h3 { color: #1d1d1f; }

css/marketing-pages.css.after:
/* Only the 21 owner-selected light originals: legacy magenta cards stay white. */
.visual-card--original .visual-card__inner { background: var(--original-image-bg, #fefefe); }
.visual-card--original .visual-card__image { object-fit: contain; object-position: 50% 100%; }
/* 44: intrinsic full-width images. The flex rail shares the tallest content-led
   height; copy can reflow. Reserve only the measured subject region below copy,
   keeping the original quiet upper pixels behind text, without scaling down. */
:is(#home-problems, #automation-uses, #planner-scenarios) .visual-card { display: flex; }
:is(#home-problems, #automation-uses, #planner-scenarios) .visual-card__inner { width: 100%; height: auto; min-height: 28.125rem; }
:is(#home-problems, #automation-uses, #planner-scenarios) .visual-card__image { inset: auto 0 0; width: 100%; height: auto; }
.visual-card--original[data-original-asset="HOME-02"] { --subject-reserve: 350 / 303; }
.visual-card--original[data-original-asset="HOME-03"] { --subject-reserve: 350 / 285; }
.visual-card--original[data-original-asset="PLANNER-04"] { --subject-reserve: 350 / 297; }
.visual-card--original[data-original-asset="AI-02"] { --subject-reserve: 350 / 381; }
.visual-card--original[data-original-asset="AI-08"] { --subject-reserve: 350 / 359; }
.visual-card--original:is([data-original-asset="HOME-02"], [data-original-asset="HOME-03"], [data-original-asset="PLANNER-04"], [data-original-asset="AI-02"], [data-original-asset="AI-08"]) .visual-card__inner::after { content: ""; display: block; flex: 0 0 auto; width: 100%; aspect-ratio: var(--subject-reserve); pointer-events: none; }
.visual-card--original .visual-card__copy,
.visual-card--original h3 { color: #1d1d1f; }

